"use strict";
const wb = {data:"",format:"csv",info:null,artifact:null,connection:null,results:null,from:0,to:0,hover:null,tradePage:0,tradeFilter:"",risk:"equity",candidates:[]};
const number = value => value == null ? "—" : Number(value).toLocaleString("en-US", {maximumFractionDigits:4});
function panel(name, title, intro, body) {
  const section=document.createElement("section");section.id=`tab-${name}`;section.className="panel";section.hidden=true;
  section.innerHTML=`<div class="page-heading"><p class="eyebrow">LOCAL RESEARCH / OPEN QUESTIONS</p><h1>${title}</h1><p>${intro}</p></div>${body}`;
  document.querySelector("main").insertBefore(section,$("results"));
  const button=document.createElement("button");button.className="nav";button.dataset.tab=name;button.innerHTML=`${name==="library"?"⌕":"◉"} <span>${name==="library"?"Data discovery":"Models & inference"}</span>`;
  document.querySelector("nav[aria-label='Research modes']").insertBefore(button,document.querySelector(".nav[data-tab='ml']"));
  button.addEventListener("click",()=>{document.querySelectorAll(".nav").forEach(b=>b.classList.toggle("active",b===button));document.querySelectorAll(".panel").forEach(p=>p.hidden=p!==section);$("page-label").textContent=name==="library"?"DATA DISCOVERY":"MODELS & INFERENCE";});
}
panel("library","Your idea can start anywhere.","Search public catalogs, inspect what a dataset actually measures, then map it into a signal. Private sales need the owner's data or authorized API.",`
<div class="source-grid"><div><div class="card"><h2>01 / Describe the question</h2><label>Your unusual hypothesis<textarea id="idea-query" rows="3">Buy $100 when ice cream sales rise, provided the market is above its moving average.</textarea></label><div class="examples" id="idea-chips"></div><label class="check"><input id="idea-use-llm" type="checkbox"> Use my configured LLM to propose the data plan (optional)</label><button id="plan-idea" class="primary">Interpret data requirements →</button><div id="idea-plan" class="idea-interpretation" hidden></div><h2 class="mt22">02 / Search the world of data</h2><div class="two-col"><label>Search terms<input id="data-query" value="ice cream sales"></label><label>Public catalog<select id="data-catalog"><option value="socrata">Public cities & governments</option><option value="worldbank">World Bank indicators</option></select></label></div><div class="examples"><button class="example-chip query-chip" data-query="traffic">Traffic</button><button class="example-chip query-chip" data-query="urban growth">Urban growth</button><button class="example-chip query-chip" data-query="weather">Weather</button><button class="example-chip query-chip" data-query="retail sales">Retail sales</button><button class="example-chip query-chip" data-query="ice cream">Ice cream</button></div><button id="search-data" class="secondary">Search public datasets</button><p class="hint">Requests go from this computer to the chosen catalog. Public access is not a blanket redistribution license. Results can be proxies or incomplete previews.</p><div id="source-status" role="status"></div></div><div id="data-candidates" class="source-results"></div></div>
<div><div class="card"><h2>03 / Import or fetch a source</h2><label>Local dataset file<input id="generic-file" type="file" accept=".csv,.json"></label><button id="load-world-demo" class="secondary">Use synthetic world-signals demo</button><p class="hint">Demo columns include ice-cream, merch and rubber-duck sales, traffic, urban growth, weather, shipping, moon phase and day type. None is real market evidence.</p><details><summary>Fetch a known HTTPS API / other connector</summary><label>Source<select id="source-kind"><option value="custom_https">Any documented HTTPS CSV/JSON API</option><option value="worldbank">World Bank indicator</option><option value="portwatch">IMF PortWatch (one example)</option></select></label><label>Source configuration JSON<textarea id="source-config" class="json-input" rows="6">{"id":"custom_https","url":"","format":"json","records_path":"","auth":"none","header_name":"X-API-Key"}</textarea></label><div class="two-col"><label>Country (World Bank)<input id="source-country" value="USA"></label><label>Optional session key<input id="source-key" type="password" autocomplete="off" placeholder="Only when this provider requires it"></label></div><button id="fetch-source" class="secondary">Fetch on this computer</button><p class="hint">No key is requested for keyless sources. For private shop/merch APIs, create your own provider key and supply its documented header. Keys stay in memory; they are omitted from exports.</p></details><div id="dataset-status" class="file-status"></div></div><div class="card"><h2>04 / Inspect and map observations</h2><div id="dataset-preview" class="source-preview"><p class="hint">Choose a file, a catalog result or the offline demo.</p></div><div class="two-col"><label>Observation time<select id="map-observed"><option value="">Choose a timestamp</option></select></label><label>Publication / available time<select id="map-available"><option value="">No publication column</option></select></label><label>Availability policy<select id="map-mode"><option value="column">Use publication column</option><option value="acquired">Available only from acquisition time</option><option value="lag">Explicit assumed historical lag</option></select></label><label>Assumed lag (hours)<input id="map-lag" type="number" min="0" value="24"></label><label>Missing timezone assumption<select id="map-timezone"><option value="">Require timezone in timestamps</option><option value="UTC">Interpret naive/date-only values as UTC</option></select></label><label>Expire observations after (hours)<input id="map-age" type="number" min="1" value="48"></label></div><p class="source-warning">Historical values may be revised. An assumed lag is an exploratory scenario, not proof the data was available then. Different sources may need aggregation, compatible geography and a longer market history.</p><div id="dataset-fields" class="feature-checks"></div><details><summary>Text signals, long-form tables & advanced mapping</summary><p class="hint">Numeric and boolean columns work directly. Categorical columns use fixed hash buckets. Text signals can explicitly count/match a phrase or measure text length. JSON objects/short numeric arrays are flattened.</p><textarea id="advanced-mapping" class="json-input" rows="7">{}</textarea></details><button id="apply-mapping" class="secondary">Validate & use these features</button><div id="mapping-warnings" class="source-warning"></div></div></div></div>`);
panel("models","A model output becomes a testable decision.","Train a small local baseline, bring a pretrained model, or connect a model/LLM you run yourself. The ZIP contains no model weights.",`
<div class="source-grid"><div class="card"><h2>01 / Inputs, target & chronology</h2><label>Workflow<select id="generic-workflow"><option value="train">Train a basic local model</option><option value="upload">Use pretrained JSON / optional ONNX</option><option value="endpoint">My local model / LLM endpoint</option></select></label><p class="hint">Uses the market CSV and execution settings from Strategy research, plus the mapped observations from Data discovery.</p><div id="model-fields" class="feature-checks"></div><div class="two-col"><label>Predict this quantity<select id="model-target"><option value="market.close">market.close</option></select></label><label>Future outcome<select id="model-target-type"><option value="increase">Probability of an increase</option><option value="return">Relative change</option><option value="level">Future numeric level</option></select></label><label>Forecast horizon (market bars)<input id="generic-horizon" type="number" min="1" max="30" value="1"></label><label>Training epochs (basic logistic)<input id="generic-epochs" type="number" min="1" max="2000" value="80"></label><label>Train fraction<input id="generic-train" type="number" step="0.05" value="0.6"></label><label>Validation fraction<input id="generic-validation" type="number" step="0.05" value="0.2"></label></div><label>Trailing feature transformations (optional JSON)<textarea id="feature-transforms" class="json-input" rows="3">[]</textarea></label><p class="hint">Example: [{"source":"ice_cream_sales","operation":"pct_change","window":7,"name":"ice_cream_growth_7"}]. Also lag, difference, mean, sum and zscore. No future observations or executable expressions.</p><details><summary>Pretrained model upload & configuration</summary><label>Model file<input id="uploaded-model" type="file" accept=".json,.onnx"></label><p id="model-file-status" class="file-status">Plain numeric JSON works without extras. ONNX Runtime is optional. Python/pickle/joblib files are not executed.</p><label>Model input → dataset column mapping JSON<textarea id="model-input-map" class="json-input" rows="3">{}</textarea></label><div class="two-col"><label>Declared trained-through date<input id="trained-through" placeholder="2022-12-31T00:00:00Z"></label><label>Evaluation start bar (optional)<input id="evaluation-start" type="number" min="0" placeholder="Default: held-out period"></label></div><label>Large local ONNX graph path (optional)<input id="local-model-path" placeholder="C:\\Models\\your-model.onnx"></label><label class="check"><input id="allow-model-path" type="checkbox"> Allow the optional local runtime to read this model and its external weights. Files stay on this computer.</label><button id="inspect-model-path" class="secondary small">Inspect local ONNX model</button><div class="two-col"><label>ONNX output name<input id="onnx-output-name" placeholder="From model inspection"></label><label>ONNX output column<input id="onnx-output-column" type="number" min="0" value="1"></label></div><p class="hint">Portable ONNX adapter: one numeric [batch,features] input and a scalar/two-column output. For larger, multimodal or other-framework models, use your own inference endpoint below. No model file is included in the release ZIP.</p></details><details id="endpoint-details"><summary>My model / LLM connection (optional)</summary><label>Service type<select id="endpoint-kind"><option value="llm">OpenAI-compatible chat endpoint (local LLM)</option><option value="tabular">My tabular prediction endpoint</option></select></label><label>Endpoint<input id="model-endpoint" value="http://127.0.0.1:11434/v1"></label><div class="two-col"><label>Your installed model name<input id="endpoint-model" placeholder="Name configured in your own server"></label><label>Optional session API key<input id="model-key" type="password" autocomplete="off"></label></div><label class="check"><input id="allow-remote-model" type="checkbox"> I choose a remote HTTPS provider; it may receive my query/features. Leave unchecked for localhost only.</label><label>Historical prompt<textarea id="model-prompt" rows="3">Given these historical features, return strict JSON only with a numeric probability that {target} increases over the next {horizon} bars: {features}</textarea></label><div class="two-col"><label>Use this output as a signal<select id="endpoint-signal"><option value="json_field">JSON numeric field</option><option value="completion_tokens">Reported output token count</option><option value="prompt_tokens">Reported input token count</option><option value="total_tokens">Reported total token count</option><option value="text_contains">Output contains a phrase</option><option value="text_length">Output character length</option></select></label><label>Output JSON field / tabular array field<input id="endpoint-output-field" value="probability"></label><label>Phrase to match<input id="endpoint-phrase" placeholder="e.g. rubber duck"></label><label>Output kind<select id="endpoint-output-kind"><option value="probability">Probability [0,1]</option><option value="prediction">Numeric measurement / token count</option></select></label><label>Maximum requests (1–64)<input id="endpoint-calls" type="number" min="1" max="64" value="8"></label><label>Maximum output tokens per call<input id="endpoint-tokens" type="number" min="1" max="2048" value="128"></label></div><button id="test-endpoint" class="secondary small">Test my connection</button><p class="budget-note">LLM replay runs now, using historical inputs. Modern model training can include future facts; this is not verified out-of-sample history. Token counts must be reported by the provider. Calls can take time and paid providers may charge you.</p><p class="hint">Tabular endpoint contract: POST {"feature_names":[...],"features":[[...]],"model":"..."} → {"predictions":[0.6,...]}. Use the exact endpoint URL and set the output field to predictions.</p></details></div>
<div><div class="card"><h2>02 / Explain how inference becomes a trade</h2><div class="model-output"><span>Configured model output</span><span>→ explicit condition</span><span>→ next-open execution</span></div><div class="two-col"><label>Comparison<select id="inference-comparison"><option>&gt;</option><option>&gt;=</option><option>&lt;</option><option>&lt;=</option></select></label><label>Threshold<input id="inference-threshold" type="number" step="0.01" value="0.5"></label><label>When condition is true<select id="inference-action"><option value="target">Target long exposure</option><option value="cash">Buy a cash amount each signal</option></select></label><label>Exposure [0–1] or cash amount<input id="inference-size" type="number" step="0.1" value="1"></label><label>When condition is false<select id="inference-false"><option value="exit">Exit to cash</option><option value="hold">Hold current position</option></select></label></div><p id="inference-summary" class="idea-interpretation">If probability &gt; 0.5, target full long exposure; otherwise exit. Orders fill at the next market bar's open.</p><label class="check"><input id="persist-local" type="checkbox"> Save this experiment on this computer. Otherwise keep it only in this app session.</label><button id="run-generic-model" class="primary full">Run inference experiment →</button><div id="generic-progress" role="status"></div></div><div class="card"><h2>03 / Inspect the gaps between ideas and trades</h2><p class="hint">The market chart shows actual simulated fills. Select a trade to inspect its model output, rule, cash, fee, slippage and resulting position. A correct sales/traffic forecast can still lose money in the market.</p><p class="callout">No operator account, cloud backend or telemetry. Your selected source/model receives only requests you choose. Uploads, provider keys and runs stay in session memory unless you explicitly save/export locally.</p><button id="export-pretrained" class="secondary">Export last numeric model JSON</button><p class="hint">The file can be uploaded again. Large local model references require the original local files or service when rerun. Hosted weights and SDKs are additional installs made by the user.</p></div></div></div>`);

const originalPayload = payload;
payload = function(mode="rules") {
  const body=originalPayload(mode);
  if(wb.data){body.feature_data=wb.data;body.feature_format=wb.format;body.feature_mapping=wb.info?.mapping || {};}
  body.transforms=JSON.parse($("feature-transforms").value||"[]");
  body.persist_local=$("persist-local").checked;
  return body;
};
const originalSetSpec=setSpec;
setSpec=function(spec){originalSetSpec(spec); updateInferenceSummary();};
document.querySelector(".nav[data-tab='ml'] span").textContent="Market ridge baseline";
document.querySelector("#tab-research h1").textContent="What if the signal is… weird?";
document.querySelector("#tab-research .page-heading>p:last-child").textContent="Bring a question, find measurable data, and see how its trading rules would have behaved.";
const privacy=document.createElement("div");privacy.className="privacy-strip";privacy.textContent="SESSION FIRST / Data, uploads and keys remain on your computer. Runs are kept in memory by default; local saving and exports are your choice. No app-operator backend.";document.querySelector("header").after(privacy);
const sharedSave=$("persist-local").closest("label");privacy.append(sharedSave);
document.querySelector("#tab-history .page-heading>p:last-child").textContent="Recent runs stay in this app session. Local persistence and exports are explicit choices.";
$("test-endpoint").textContent="Test LLM connection";
let showSavedRuns=false;
function renderRuns(values){
 $("history-list").innerHTML=values.length?`<div class="table-scroll"><table><thead><tr><th>Select</th><th>Experiment</th><th>Mode</th><th>Return</th><th>Actions</th></tr></thead><tbody>${values.map(r=>`<tr><td><input type="checkbox" name="compare" value="${r.id}" aria-label="Select ${escapeHTML(r.name)}"></td><td>${escapeHTML(r.name)}<br><span class="hint">${escapeHTML(r.created_at?.slice(0,16))}</span></td><td>${escapeHTML(r.mode)}</td><td>${pct(r.summary?.total_return)}</td><td><button class="text-button" data-view="${r.id}">View</button><button class="text-button" data-rerun="${r.id}">Rerun</button></td></tr>`).join("")}</tbody></table></div>`:'<p>No runs in this session. Include saved local runs only when you choose.</p>';
 $("history-list").querySelectorAll("[data-view]").forEach(b=>b.addEventListener("click",()=>action(b,async()=>showResult(await api(`/api/experiments/${b.dataset.view}`)))));
 $("history-list").querySelectorAll("[data-rerun]").forEach(b=>b.addEventListener("click",()=>action(b,async()=>showResult(await api("/api/rerun",{id:b.dataset.rerun,persist_local:$("persist-local").checked,model_credential:$("model-key").value||undefined})))));
}
refreshHistory=async()=>renderRuns(await api(`/api/history${showSavedRuns?"?include_saved=1":""}`));
const oldRefresh=$("refresh-history"),freshRefresh=oldRefresh.cloneNode(true);oldRefresh.replaceWith(freshRefresh);on("refresh-history",refreshHistory);
const savedButton=document.createElement("button");savedButton.className="secondary small";savedButton.textContent="Include explicitly saved local runs";savedButton.addEventListener("click",()=>action(savedButton,async()=>{showSavedRuns=true;await refreshHistory();}));$("refresh-history").after(savedButton);

function selectedFeatures(){return [...document.querySelectorAll('input[name="generic-feature"]:checked')].map(el=>el.value);}
function mappingFromForm(){
  let extra={};try{extra=JSON.parse($("advanced-mapping").value || "{}");}catch{throw new Error("Advanced mapping must be a JSON object.");}
  return {...(wb.info?.mapping||{}),...extra,observed_at_column:$("map-observed").value,timestamp_column:$("map-observed").value,available_at_column:$("map-available").value,availability_mode:$("map-mode").value,availability_lag_hours:Number($("map-lag").value),timezone:$("map-timezone").value,max_age_hours:Number($("map-age").value),field_columns:[...document.querySelectorAll('input[name="map-numeric"]:checked')].map(el=>el.value),categorical_columns:[...document.querySelectorAll('input[name="map-category"]:checked')].map(el=>el.value)};
}
function syncRuleOptions(){
 if(!wb.info)return; const fields=wb.info.generated_fields;
 document.querySelectorAll("#conditions .left").forEach(select=>fields.forEach(name=>{const value=`event:${name}`;if(![...select.options].some(o=>o.value===value)){const option=document.createElement("option");option.value=value;option.textContent=name;select.append(option);}}));
}
function updateFields(reset=false){
  if(!wb.info)return;
  const previous=new Set(selectedFeatures()),oldTarget=$("model-target").value,hadFields=$("model-fields").children.length>0;
  let transformed=[];try{const definitions=JSON.parse($("feature-transforms").value||"[]");if(Array.isArray(definitions))transformed=definitions.map(t=>t.name).filter(n=>typeof n==="string"&&n);}catch{}
  const fields=[...new Set([...wb.info.generated_fields,...transformed])];
  $("model-fields").innerHTML=fields.map((name,i)=>`<label class="check"><input name="generic-feature" type="checkbox" value="${escapeHTML(name)}" ${(reset||!hadFields?i<5:previous.has(name))?"checked":""}>${escapeHTML(name)}</label>`).join("")+`<label class="check"><input name="generic-feature" type="checkbox" value="market.return_1" ${previous.has("market.return_1")?"checked":""}>market.return_1</label>`;
  $("model-target").innerHTML='<option value="market.close">market.close</option>'+[...new Set([...wb.info.mapping.field_columns,...transformed])].map(name=>`<option>${escapeHTML(name)}</option>`).join("");
  if(!reset&&[...$("model-target").options].some(o=>o.value===oldTarget))$("model-target").value=oldTarget;
  document.querySelectorAll("#conditions .left").forEach(select=>fields.forEach(name=>{const value=`event:${name}`;if(![...select.options].some(o=>o.value===value)){const option=document.createElement("option");option.value=value;option.textContent=name;select.append(option);}}));
}
function showDataset(info,content,format){
  const reset=wb.data!==content;wb.info=info;wb.data=content;wb.format=format;
  $("dataset-status").textContent=`${info.rows} observations · ${info.columns.length} columns · ${format.toUpperCase()} · session memory`;
  const options=info.columns.map(name=>`<option value="${escapeHTML(name)}">${escapeHTML(name)}</option>`).join("");
  $("map-observed").innerHTML='<option value="">Choose observation time</option>'+options;$("map-observed").value=info.mapping.observed_at_column;
  $("map-available").innerHTML='<option value="">No publication column</option>'+options;$("map-available").value=info.mapping.available_at_column;
  $("map-mode").value=info.mapping.availability_mode;$("map-timezone").value=info.mapping.timezone||"";$("map-age").value=info.mapping.max_age_hours;$("map-lag").value=info.mapping.availability_lag_hours ?? 24;
  $("dataset-fields").innerHTML=info.numeric_fields.map(name=>`<label class="check"><input name="map-numeric" type="checkbox" value="${escapeHTML(name)}" ${info.mapping.field_columns.includes(name)?"checked":""}>${escapeHTML(name)}</label>`).join("")+info.categorical_fields.map(name=>`<label class="check"><input name="map-category" type="checkbox" value="${escapeHTML(name)}" ${info.mapping.categorical_columns.includes(name)?"checked":""}>${escapeHTML(name)} · categorical</label>`).join("");
  const columns=info.columns.slice(0,8);$("dataset-preview").innerHTML=`<table><thead><tr>${columns.map(name=>`<th>${escapeHTML(name)}</th>`).join("")}</tr></thead><tbody>${info.preview.slice(0,5).map(row=>`<tr>${columns.map(name=>`<td>${escapeHTML(String(row[name]??"").slice(0,80))}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
  $("mapping-warnings").textContent=info.warnings.join(" ");updateFields(reset);
}
async function useData(content,format="csv",mapping){const info=await api("/api/dataset/inspect",{content,format,mapping});showDataset(info,content,format);return info;}
function connectionConfig(){
  const kind=$("endpoint-kind").value;
  return {kind,endpoint:$("model-endpoint").value.trim(),model:$("endpoint-model").value.trim(),allow_remote:$("allow-remote-model").checked,prompt:$("model-prompt").value,signal:$("endpoint-signal").value,output_field:$("endpoint-output-field").value.trim() || (kind==="tabular"?"predictions":"probability"),phrase:$("endpoint-phrase").value,output_kind:$("endpoint-output-kind").value,max_calls:Number($("endpoint-calls").value),max_tokens:Number($("endpoint-tokens").value),temperature:0};
}
function updateInferenceSummary(){
  if(!$("inference-threshold"))return;
  const output=$("generic-workflow").value==="endpoint"?$("endpoint-signal").selectedOptions[0].textContent:$("model-target-type").value==="increase"?`probability of ${$("model-target").value} increasing`:`predicted ${$("model-target").value}`;
  $("inference-summary").textContent=`If ${output} ${$("inference-comparison").value} ${$("inference-threshold").value}, ${$("inference-action").value==="cash"?`buy up to ${money(Number($("inference-size").value))} including fees`:`target ${pct(Number($("inference-size").value))} long exposure`}; otherwise ${$("inference-false").value==="hold"?"hold":"exit to cash"}. Fill at the next supplied open with the selected costs.`;
}
["generic-workflow","model-target","model-target-type","inference-comparison","inference-threshold","inference-action","inference-size","inference-false","endpoint-signal"].forEach(id=>$(id).addEventListener("change",updateInferenceSummary));
document.querySelectorAll(".query-chip").forEach(button=>button.addEventListener("click",()=>{$("data-query").value=button.dataset.query;}));
on("plan-idea",async()=>{
  const body={query:$("idea-query").value,fields:wb.info?.generated_fields||[]};
  if($("idea-use-llm").checked){body.connection=connectionConfig();body.credential=$("model-key").value;}
  const plan=await api("/api/ideas/plan",body);$("data-query").value=plan.search_terms;$("idea-plan").hidden=false;
  $("idea-plan").textContent=`Search for: ${plan.search_terms}\n\n${plan.data_requirements.map(r=>r.measurement+" "+r.required_fields.join(", ")).join("\n")}\n\nSignal proposal: ${plan.signals.map(s=>s.definition).join(" ")}\n\n${plan.clarifications.join("\n")}\n\n${plan.llm_plan?JSON.stringify(plan.llm_plan,null,2):plan.warnings[0]}`;
});
on("search-data",async()=>{
  $("source-status").textContent="Searching the selected public catalog from this computer…";
  const value=await api("/api/sources/search",{query:$("data-query").value,catalog:$("data-catalog").value});wb.candidates=value.datasets;
  $("source-status").textContent=`${value.datasets.length} candidate sources. ${value.warnings[0]}`;
  $("data-candidates").innerHTML=value.datasets.map((item,index)=>`<article class="source-result"><span class="tag">${escapeHTML(item.provider)}</span><h3>${escapeHTML(item.title)}</h3><p>${escapeHTML(item.description)}</p><p>${escapeHTML(item.license)} · ${escapeHTML(item.access)}</p><div class="toolbar"><button class="secondary small" data-fetch="${index}">Fetch preview / data</button><a href="${escapeHTML(item.page)}" target="_blank" rel="noreferrer">Inspect source & terms ↗</a></div></article>`).join("") || '<div class="card"><h2>No exact source found</h2><p>Try another phrase or catalog, import an owner-authorized export, or configure a documented source API. The app does not substitute unrelated proxies.</p></div>';
  $("data-candidates").querySelectorAll("[data-fetch]").forEach(button=>button.addEventListener("click",()=>action(button,async()=>{
    const candidate=wb.candidates[Number(button.dataset.fetch)],config={...candidate.config};if(config.id==="worldbank")config.country=$("source-country").value.trim();
    $("source-config").value=JSON.stringify(config,null,2);const fetched=await api("/api/sources/fetch",{config,credential:$("source-key").value||undefined});
    await useData(fetched.content,fetched.format,fetched.mapping_suggestion);$("mapping-warnings").textContent=fetched.warnings.join(" ");$("source-key").value="";message(`Fetched ${fetched.name}. Review time, availability, measurement and licensing before running.`);
  })));
});
$("generic-file").addEventListener("change",async()=>{const file=$("generic-file").files[0];if(!file)return;try{if(file.size>4000000)throw new Error("Use a CSV/JSON file under 4 MB; use a local model endpoint for large workloads.");await useData(await file.text(),file.name.toLowerCase().endsWith(".json")?"json":"csv");}catch(error){message(error.message,true);}});
let demoText="";
on("load-world-demo",async()=>{if(!demoText)demoText=(await api("/api/bootstrap")).feature_demo;await useData(demoText);message("Synthetic multi-domain signals selected. These are software examples, not real sales or market evidence.");});
on("fetch-source",async()=>{const config=JSON.parse($("source-config").value);const value=await api("/api/sources/fetch",{config,credential:$("source-key").value||undefined});await useData(value.content,value.format,value.mapping_suggestion);$("mapping-warnings").textContent=value.warnings.join(" ");$("source-key").value="";});
$("source-kind").addEventListener("change",()=>{const id=$("source-kind").value;const config=id==="worldbank"?{id,indicator:"SP.URB.GROW",country:$("source-country").value,start:"2000",end:"2024"}:id==="portwatch"?{id,port_id:"port0",start:"2023-01-01",end:"2024-05-31"}:{id,url:"",format:"json",records_path:"",auth:"none",header_name:"X-API-Key"};$("source-config").value=JSON.stringify(config,null,2);});
