$("uploaded-model").addEventListener("change",async()=>{const file=$("uploaded-model").files[0];if(!file)return;try{
  if(file.size>5000000)throw new Error("For a large model, use the local path or your own model endpoint. Model weights are not copied into the ZIP.");
  if(file.name.toLowerCase().endsWith(".onnx")){const bytes=new Uint8Array(await file.arrayBuffer());let raw="";for(let i=0;i<bytes.length;i+=16384)raw+=String.fromCharCode(...bytes.subarray(i,i+16384));wb.artifact={format:"onnx",data_base64:btoa(raw)};}
  else wb.artifact={format:"json",model:JSON.parse(await file.text())};
  const result=await api("/api/model/inspect",{artifact:wb.artifact});configureModelInputs(result);$("model-file-status").textContent=`${file.name}: ${JSON.stringify(result)}`;$("generic-workflow").value="upload";
}catch(error){wb.artifact=null;message(error.message,true);}});
on("inspect-model-path",async()=>{wb.artifact={format:"onnx",model_path:$("local-model-path").value.trim(),allow_local_file:$("allow-model-path").checked};const value=await api("/api/model/inspect",{artifact:wb.artifact});configureModelInputs(value);$("model-file-status").textContent=JSON.stringify(value);$("generic-workflow").value="upload";});
on("test-endpoint",async()=>{if($("endpoint-kind").value==="tabular")throw new Error("Test a tabular service with a bounded replay using its mapped feature inputs. This connection test sends a chat prompt only.");const value=await api("/api/connections/test",{connection:connectionConfig(),credential:$("model-key").value||undefined});message(`Connected to ${value.reported_model}; ${value.completion_tokens??"unreported"} output tokens. ${value.text}`);});
on("run-generic-model",async()=>{
  if(!wb.data){if(!demoText)demoText=(await api("/api/bootstrap")).feature_demo;await useData(demoText);}
  const mode=$("generic-workflow").value==="endpoint"?"endpoint":"model",body=payload(mode),targetType=$("model-target-type").value;
  body.name=`${$("name").value||"Unusual signal"} · ${$("model-target").value}`;
  body.transforms=JSON.parse($("feature-transforms").value||"[]");
  body.model_config={feature_names:$("ordered-inputs")?.value.trim()?$("ordered-inputs").value.split(",").map(s=>s.trim()).filter(Boolean):selectedFeatures(),target_field:$("model-target").value,target_type:targetType,model_family:targetType==="increase"?"logistic":"ridge",horizon:Number($("generic-horizon").value),epochs:Number($("generic-epochs").value),train_fraction:Number($("generic-train").value),validation_fraction:Number($("generic-validation").value),l2_candidates:[0.01,0.1],decision:{comparison:$("inference-comparison").value,threshold:Number($("inference-threshold").value),when_true:$("inference-action").value==="cash"?{buy_cash:Number($("inference-size").value)}:{target_weight:Number($("inference-size").value)},when_false:$("inference-false").value},feature_mapping:JSON.parse($("model-input-map").value||"{}")};
  if($("trained-through").value.trim())body.model_config.trained_through=$("trained-through").value.trim();
  if($("evaluation-start").value!=="")body.model_config.evaluation_start_index=Number($("evaluation-start").value);
  if($("generic-workflow").value==="upload"){if(!wb.artifact)throw new Error("Upload and inspect a supported model, or choose a local ONNX path.");body.pretrained={...wb.artifact,feature_mapping:body.model_config.feature_mapping};if(body.pretrained.model_path){body.pretrained.model_path=$("local-model-path").value.trim();body.pretrained.allow_local_file=$("allow-model-path").checked;}body.model_config.output_name=$("onnx-output-name").value||undefined;body.model_config.output_column=Number($("onnx-output-column").value);}
  if(mode==="endpoint"){body.connection=connectionConfig();body.model_credential=$("model-key").value||undefined;}
  $("generic-progress").textContent=mode==="endpoint"?`Running at most ${body.connection.max_calls} requests to the endpoint you selected…`:"Training on the past, selecting on validation and evaluating the held-out period…";
  const result=await api("/api/run",body);$("generic-progress").textContent="Complete. Inspect model outputs, cash, positions and fills below.";showResult(result);
});
