on("interpret",async()=>{
 const text=$("hypothesis").value;
 try {setSpec(await api("/api/parse",{text,fields:wb.info?.generated_fields||[]}));message("Supported rule interpreted. Review it before running.");}
 catch(error){
  const body={query:text,fields:wb.info?.generated_fields||[]};
  if($("idea-use-llm").checked){body.connection=connectionConfig();body.credential=$("model-key").value||undefined;}
  const plan=await api("/api/ideas/plan",body);$("idea-query").value=text;$("data-query").value=plan.search_terms;
  $("idea-plan").hidden=false;$("idea-plan").textContent=`Data search: ${plan.search_terms}\n\n${plan.data_requirements.map(r=>r.measurement).join("\n")}\n\n${plan.signals.map(r=>r.definition).join("\n")}\n\n${plan.clarifications.join("\n")}`;
  document.querySelector(".nav[data-tab='library']").click();message("The idea needs data/definitions first. Review the proposed plan, search candidates and map exact measurements; no trading rules were guessed.");
 }
});

// Guided source setup: JSON remains available for advanced provider parameters.
const ownApi=document.createElement("div");ownApi.id="own-api-form";ownApi.innerHTML=`<label>Your data API URL<input id="own-api-url" type="url" placeholder="https://your-provider.example/data"></label><div class="two-col"><label>Response format<select id="own-api-format"><option value="json">JSON records</option><option value="csv">CSV table</option></select></label><label>Record array path (JSON)<input id="own-api-records" placeholder="e.g. data.items"></label><label>Authentication<select id="own-api-auth"><option value="none">None / public source</option><option value="bearer">Bearer token (your key)</option><option value="api_key">API key header</option></select></label><label>API-key header name<input id="own-api-header" value="X-API-Key"></label></div><p class="hint">Use your provider's documented GET endpoint. Query parameters belong in the URL; credentials belong in the separate masked session field. Private sales must come from an authorized owner export/API.</p>`;
$("source-kind").closest("label").after(ownApi);
function syncOwnApi(){if($("source-kind").value!=="custom_https")return;$("source-config").value=JSON.stringify({id:"custom_https",url:$("own-api-url").value.trim(),format:$("own-api-format").value,records_path:$("own-api-records").value.trim(),auth:$("own-api-auth").value,header_name:$("own-api-header").value.trim()},null,2);}
["own-api-url","own-api-format","own-api-records","own-api-auth","own-api-header"].forEach(id=>$(id).addEventListener("input",syncOwnApi));$("source-kind").addEventListener("change",()=>{ownApi.hidden=$("source-kind").value!=="custom_https";});

const timeOptions='<option value="iso">ISO timestamp / date</option><option value="unix_seconds">Unix seconds</option><option value="unix_milliseconds">Unix milliseconds</option>';
const timeFormats=document.createElement("div");timeFormats.className="two-col";timeFormats.innerHTML=`<label>Observation time format<select id="map-observed-format">${timeOptions}</select></label><label>Publication time format<select id="map-available-format">${timeOptions}</select></label>`;$("map-mode").closest(".two-col").after(timeFormats);
const originalMappingFromForm=mappingFromForm;
mappingFromForm=function(){return {...originalMappingFromForm(),timestamp_format:$("map-observed-format").value,available_at_format:$("map-available-format").value};};

const marketImport=document.createElement("details");marketImport.innerHTML=`<summary>Use this API/file as the market dataset</summary><p class="hint">Map actual completed-bar prices. Missing open/high/low/close prices are never fabricated. Observation time is the market bar's open time.</p><div class="two-col">${["open","high","low","close","volume"].map(name=>`<label>${name.toUpperCase()} column<select id="market-map-${name}"><option value="">Choose a column</option></select></label>`).join("")}</div><button id="use-as-market" class="secondary small">Use mapped OHLCV as market data</button>`;$("apply-mapping").after(marketImport);
on("use-as-market",async()=>{if(!wb.data)throw new Error("Import or fetch a table first.");const mapping={timestamp_column:$("map-observed").value,timezone:$("map-timezone").value,timestamp_format:$("map-observed-format").value};for(const field of ["open","high","low","close","volume"])mapping[field]=$("market-map-"+field).value;const result=await api("/api/dataset/market",{content:wb.data,format:wb.format,mapping});marketCSV=result.market_csv;$("instrument-label").textContent="Your mapped market data";$("fixture-tag").textContent=`USER MARKET DATA · ${result.rows} BARS`;$("data-label").textContent=`${result.start.slice(0,10)} → ${result.end.slice(0,10)}. Set the actual bar duration before running. ${result.warnings.join(" ")}`;message("Your API/file is now the market input. Review the interval and choose a separate feature dataset if needed.");});

const transformBuilder=document.createElement("details");transformBuilder.innerHTML=`<summary>Build a trailing signal without writing JSON</summary><div class="two-col"><label>Source field<select id="transform-source"></select></label><label>Measurement<select id="transform-operation"><option value="pct_change">Relative change</option><option value="difference">Absolute difference</option><option value="lag">Lagged value</option><option value="mean">Rolling mean</option><option value="sum">Rolling sum</option><option value="zscore">Trailing z-score</option></select></label><label>Past market bars<input id="transform-window" type="number" min="1" max="1000" value="7"></label><label>New signal name<input id="transform-name" placeholder="Auto-name from the definition"></label></div><button id="add-transform" class="secondary small">Add this signal</button><p class="hint">Windows count supplied market bars. The definition uses only data available at each decision close.</p>`;$("feature-transforms").closest("label").before(transformBuilder);
on("add-transform",async()=>{const source=$("transform-source").value,operation=$("transform-operation").value,window=Number($("transform-window").value),name=$("transform-name").value.trim()||`${source}_${operation}_${window}`;if(!source)throw new Error("Map a source dataset first.");const transforms=JSON.parse($("feature-transforms").value||"[]");transforms.push({source,operation,window,name});$("feature-transforms").value=JSON.stringify(transforms,null,2);updateFields(false);const checkbox=[...document.querySelectorAll('input[name="generic-feature"]')].find(el=>el.value===name);if(checkbox)checkbox.checked=true;message(`Added ${name}. Review the selected model inputs and target.`);});

const textBuilder=document.createElement("details");textBuilder.innerHTML=`<summary>Measure a text field explicitly</summary><div class="two-col"><label>Text column<select id="text-source"></select></label><label>Measurement<select id="text-operation"><option value="count">Phrase count</option><option value="contains">Phrase present (0/1)</option><option value="length">Character length</option></select></label><label>Phrase<input id="text-needle" placeholder="e.g. limited edition"></label><label>Signal name<input id="text-name" value="text_signal"></label></div><button id="add-text-signal" class="secondary small">Add text measurement</button>`;$("advanced-mapping").closest("details").before(textBuilder);
on("add-text-signal",async()=>{const mapping=mappingFromForm();mapping.text_features=[...(mapping.text_features||[]),{column:$("text-source").value,operation:$("text-operation").value,needle:$("text-needle").value,name:$("text-name").value.trim()}];$("advanced-mapping").value=JSON.stringify({text_features:mapping.text_features},null,2);await useData(wb.data,wb.format,mapping);message("Text measurement added. It becomes a numeric input; no sentiment or causality was guessed.");});

const orderedInputs=document.createElement("label");orderedInputs.textContent="Exact model feature order (optional, comma separated)";const orderInput=document.createElement("input");orderInput.id="ordered-inputs";orderInput.placeholder="For pretrained tensor/service models; otherwise use the checked inputs";orderedInputs.append(orderInput);$("model-input-map").closest("label").before(orderedInputs);
const visualMapping=document.createElement("div");visualMapping.id="visual-model-mapping";$("model-input-map").closest("label").before(visualMapping);
function configureModelInputs(info){
 if(info.format==="onnx"){const outputs=info.outputs.filter(o=>/float|double/.test(o.type));if(outputs.length===1){$("onnx-output-name").value=outputs[0].name;$("onnx-output-column").value=outputs[0].shape?.[1]===2?1:0;}}
 if(!info.feature_names)return;let derived=[];try{derived=JSON.parse($("feature-transforms").value||"[]").map(item=>item.name).filter(name=>typeof name==="string"&&name);}catch{}const fields=[...new Set([...(wb.info?.generated_fields||[]),...derived,"market.close","market.volume","market.return_1"])];
 visualMapping.innerHTML='<p class="hint">Map each pretrained input to a local measured column.</p>'+info.feature_names.map(name=>`<label>${escapeHTML(name)}<select data-model-input="${escapeHTML(name)}"><option value="">Choose its local column</option>${fields.map(field=>`<option value="${escapeHTML(field)}" ${field===name?"selected":""}>${escapeHTML(field)}</option>`).join("")}</select></label>`).join("");
 visualMapping.querySelectorAll("select").forEach(select=>select.addEventListener("change",()=>{$("model-input-map").value=JSON.stringify(Object.fromEntries([...visualMapping.querySelectorAll("select")].filter(el=>el.value).map(el=>[el.dataset.modelInput,el.value])),null,2);}));
}
const baseShowDataset=showDataset;
showDataset=function(info,content,format){baseShowDataset(info,content,format);$("map-observed-format").value=info.mapping.timestamp_format||"iso";$("map-available-format").value=info.mapping.available_at_format||"iso";for(const field of ["open","high","low","close","volume"]){const select=$("market-map-"+field);select.innerHTML='<option value="">Not mapped</option>'+info.columns.map(name=>`<option>${escapeHTML(name)}</option>`).join("");const match=info.columns.find(name=>name.toLowerCase()===field);if(match)select.value=match;}$("transform-source").innerHTML=info.generated_fields.map(name=>`<option>${escapeHTML(name)}</option>`).join("");$("text-source").innerHTML=info.categorical_fields.map(name=>`<option>${escapeHTML(name)}</option>`).join("");};
$("endpoint-signal").addEventListener("change",()=>{$("endpoint-output-kind").value=["completion_tokens","prompt_tokens","total_tokens","text_length"].includes($("endpoint-signal").value)?"prediction":"probability";updateInferenceSummary();});
